values
    ("LOC_BUILDING_BURJ_KHALIFA_DESCRIPTION_CORP",                    "Allows to creat unique [ICON_RESOURCE_KHALIFA] Product where the wonder is built. Automatically themed when all slots are filled, with +200% theming bonus. +15% [ICON_Culture] Culture and [ICON_Gold] Gold in this city. Generate [ICON_RESOURCE_OIL] Oil Resource on Desert tiles whithin 6 plots which do not have any resource, improvement, district or wonder. Every time create a [ICON_Greatwork_Product] Product, gain [ICON_GreatMerchant] Great Merchant Points equal to 15% of the next [ICON_GreatMerchant] Great Merchant's cost. [NEWLINE][NEWLINE]Must be built on flat Desert tiles."),
    ("LOC_BUILDING_BURJ_KHALIFA_DESCRIPTION_CORP_JNR",                "Allows to creat unique [ICON_RESOURCE_KHALIFA] Products in the City. Automatically themed when all slots are filled, with +200% theming bonus. [ICON_Greatwork_Product] Products in Cities with Grand Hotel provide +200% [ICON_Tourism] Tourism. +15% [ICON_Culture] Culture and [ICON_Gold] Gold in this city. Generate [ICON_RESOURCE_OIL] Oil Resource on Desert tiles whithin 6 plots which do not have any resource, improvement, district or wonder. Every time create a [ICON_Greatwork_Product] Product, gain [ICON_GreatMerchant] Great Merchant Points equal to 15% of the next [ICON_GreatMerchant] Great Merchant's cost. [NEWLINE][NEWLINE]Must be built on flat Desert tiles."),
    
    ("LOC_RESOURCE_KHALIFA_NAME",                                     "[ICON_DISTRICT_WONDER] Burj Khalifa® Unique [ICON_RESOURCE_KHALIFA] Product"),
    ("LOC_PROJECT_CREATE_PRODUCT_KHALIFA_NAME",                       "[ICON_DISTRICT_WONDER] Burj Khalifa®: Create new Unique [ICON_RESOURCE_KHALIFA] Product"),
    ("LOC_PROJECT_CREATE_PRODUCT_KHALIFA_SHORT_NAME",                 "[ICON_DISTRICT_WONDER] Create new Unique [ICON_RESOURCE_KHALIFA] Product of Burj Khalifa®"),
    ("LOC_PROJECT_CREATE_PRODUCT_KHALIFA_DESCRIPTION",                "Allows creation of unique [ICON_RESOURCE_KHALIFA] Products (max. 8) when [ICON_DISTRICT_WONDER] Burj Khalifa is built."),
    
    ("LOC_GREATWORK_PRODUCT_KHALIFA_1_NAME",                          "Dubai Dried Date"),
