    ("LOC_GREATWORK_PRODUCT_KHALIFA_3_NAME",                          "Hand-made Pistachio Ice-cream"),
    ("LOC_GREATWORK_PRODUCT_KHALIFA_4_NAME",                          "Arabica coffee"),
    ("LOC_GREATWORK_PRODUCT_KHALIFA_5_NAME",                          "Arabic Calligraphy Carpet"),
    ("LOC_GREATWORK_PRODUCT_KHALIFA_6_NAME",                          "Anatolian Honey"),
    ("LOC_GREATWORK_PRODUCT_KHALIFA_7_NAME",                          "Oud"),
    ("LOC_GREATWORK_PRODUCT_KHALIFA_8_NAME",                          "Lawrence of Arabia"),

    ("LOC_PRODUCT_HD_KHALIFA_1_BONUS_DESCRIPTION",                    "+15% [ICON_FOOD] food to this city."),
    ("LOC_PRODUCT_HD_KHALIFA_2_BONUS_DESCRIPTION",                    "[ICON_FOOD] Food consumption of citizens in this city reduce by 0.5."),
    ("LOC_PRODUCT_HD_KHALIFA_3_BONUS_DESCRIPTION",                    "+4 [ICON_AMENITIES] Amenity to this city."),
    ("LOC_PRODUCT_HD_KHALIFA_4_BONUS_DESCRIPTION",                    "Citizens in this city provide +1 [ICON_SCIENCE] Science and [ICON_CULTURE] Culture."),
    ("LOC_PRODUCT_HD_KHALIFA_5_BONUS_DESCRIPTION",                    "+100% Campuss district adjacency bonuses to this city."),
    ("LOC_PRODUCT_HD_KHALIFA_6_BONUS_DESCRIPTION",                    "+1 [ICON_FOOD] Food and [ICON_PRODUCTION] Production from all [ICON_TradeRoute] domestic Trade Routes to this city."),
    ("LOC_PRODUCT_HD_KHALIFA_7_BONUS_DESCRIPTION",                    "+1 [ICON_SCIENCE] Science and [ICON_CULTURE] Culture from all [ICON_TradeRoute] domestic Trade Routes to this city."),
